    "description": "CÔNG TY TNHH KUCHEN VIỆT NAM đang tìm kiếm Nhân Viên IT – Lập Trình & Quản Trị Hệ Thống.\n\n* Quản trị, giám sát hệ thống server Windows Server 2016/2019/2022 và Linux.\n* Vận hành hệ thống ảo hóa VMware ESXi / vCenter, quản lý máy ảo.\n* Quản trị hệ thống Active Directory, GPO, DNS, DHCP, File Server.\n* Cấu hình, quản lý hệ thống email Exchange Server / Microsoft 365.\n* Thiết lập và vận hành hệ thống backup Veeam, Acronis, đảm bảo an toàn dữ liệu.\n* Giám sát hệ thống bằng các công cụ monitoring (Zabbix, PRTG, Nagios).\n* Xây dựng tài liệu kỹ thuật, quy trình vận hành chuẩn (SOP) cho hệ thống.\n* Phối hợp với vendor và các phòng ban liên quan trong các dự án hạ tầng IT.",
