      "Kinh nghiệm quản trị Active Directory, DNS, DHCP, Group Policy.",
      "Có kinh nghiệm với hệ thống sao lưu (Veeam, Acronis) và giám sát (Zabbix, Nagios).",
      "Kỹ năng scripting (PowerShell, Bash) là một lợi thế.",
      "Ưu tiên ứng viên có chứng chỉ MCSA, MCSE, RHCE, VCP."
