    "description": "Công Ty Cổ Phần A25 Hotel tuyển dụng IT Administrative Officer.\n\n* Quản trị hệ thống máy chủ\n* Cài đặt, cấu hình và quản trị các máy chủ vật lý và ảo hóa (VMware vSphere, Proxmox, Hyper-V).\n* Quản lý hệ thống lưu trữ SAN/NAS, thiết lập và giám sát backup/restore dữ liệu.\n* Theo dõi hiệu năng, dung lượng máy chủ, đảm bảo uptime 99.9%.\n\n* Vận hành hạ tầng mạng\n* Quản trị Active Directory, Group Policy, DNS, DHCP trên môi trường Windows Server.\n* Quản trị hệ thống Linux Server (CentOS/Ubuntu/RedHat), dịch vụ web (Nginx, Apache), database (MySQL, PostgreSQL).\n* Triển khai và duy trì hệ thống giám sát (Zabbix, Nagios, Grafana, Prometheus).\n\n* Bảo mật & sao lưu\n* Thiết lập và quản lý chính sách bảo mật, firewall, IDS/IPS.\n* Thực hiện sao lưu dữ liệu định kỳ, kiểm tra khả năng phục hồi (DR Test).\n* Cập nhật bản vá bảo mật, rà soát lỗ hổng hệ thống.\n\n* Hỗ trợ và tối ưu\n* Hỗ trợ kỹ thuật cho các team phát triển về môi trường hạ tầng.\n* Tối ưu hóa tài nguyên hệ thống, tiết kiệm chi phí vận hành.\n* Nghiên cứu và đề xuất giải pháp công nghệ mới.",
